(()=>{'use strict';
const key='shivam-cookie-choice-v1';const readChoice=()=>{try{const value=JSON.parse(localStorage.getItem(key)||'null');return value?.version===1?value:null}catch{return null}};
const create=(tag,attrs={},text)=>{const el=document.createElement(tag);for(const [k,v] of Object.entries(attrs))el.setAttribute(k,v);if(text)el.textContent=text;return el};
function persist(choice){const value={version:1,choice,essential:true,analytics:false,marketing:false,savedAt:new Date().toISOString()};try{localStorage.setItem(key,JSON.stringify(value))}catch{}hideBanner();document.dispatchEvent(new CustomEvent('shivam-cookie-choice',{detail:value}))}
const banner=create('section',{class:'cookie-banner',role:'region','aria-label':'Cookie choices'});banner.innerHTML='<div><strong>Cookie choices</strong><p>We currently use essential website/security services only. No optional analytics or advertising trackers are installed. <a href="/cookie-policy.html">Cookie Policy</a></p></div><div class="cookie-actions"><button type="button" data-choice="accept">Accept</button><button type="button" data-choice="reject">Reject</button><button type="button" data-manage>Manage</button></div><button type="button" class="cookie-close" aria-label="Continue with essential services only">×</button>';document.body.append(banner);
function sizeBanner(){document.documentElement.style.setProperty('--cookie-banner-height',banner.hidden?'0px':banner.getBoundingClientRect().height+'px')}
function showBanner(){banner.hidden=false;document.body.dataset.cookieBanner='open';sizeBanner()}
function hideBanner(){banner.hidden=true;delete document.body.dataset.cookieBanner;sizeBanner()}
banner.querySelectorAll('[data-choice]').forEach(b=>b.addEventListener('click',()=>persist(b.dataset.choice)));banner.querySelector('.cookie-close').addEventListener('click',()=>persist('reject'));
const preferences=create('dialog',{class:'compliance-dialog','aria-labelledby':'cookie-title'});preferences.innerHTML='<button type="button" class="dialog-close" aria-label="Close cookie preferences">×</button><h2 id="cookie-title">Cookie preferences</h2><p><strong>Essential:</strong> website delivery, security, owner sign-in and your choice record. These are necessary functions, not advertising preferences.</p><label class="consent-line"><input type="checkbox" disabled><span>Analytics — not installed or active.</span></label><label class="consent-line"><input type="checkbox" disabled><span>Advertising / marketing — not installed or active.</span></label><p>No optional categories are enabled by these controls. New optional tools will need an updated notice and appropriate opt-in before activation.</p><div class="cookie-actions"><button type="button" data-save>Save essential-only preferences</button><button type="button" data-reject>Reject optional services</button></div>';document.body.append(preferences);preferences.querySelector('.dialog-close').addEventListener('click',()=>preferences.close());preferences.querySelector('[data-save]').addEventListener('click',()=>{persist('managed');preferences.close()});preferences.querySelector('[data-reject]').addEventListener('click',()=>{persist('reject');preferences.close()});
const manage=()=>preferences.showModal();banner.querySelector('[data-manage]').addEventListener('click',manage);document.querySelectorAll('[data-cookie-preferences]').forEach(b=>b.addEventListener('click',manage));window.addEventListener('resize',sizeBanner);if(window.ResizeObserver)new ResizeObserver(sizeBanner).observe(banner);if(readChoice())hideBanner();else showBanner();
const consent=create('dialog',{class:'compliance-dialog whatsapp-consent-dialog','aria-labelledby':'whatsapp-consent-title'});consent.innerHTML='<button type="button" class="dialog-close" aria-label="Cancel WhatsApp contact">×</button><h2 id="whatsapp-consent-title">Continue to WhatsApp?</h2><p>WhatsApp is an external service. Your number and any message you send will be handled by WhatsApp and Shivam Epoxy Flooring to respond to your enquiry. You are not signing up for promotions.</p><label class="consent-line"><input type="checkbox" id="whatsapp-consent"><span>I agree to the use of my details to respond to this enquiry, as explained in the <a href="/privacy-policy.html">Privacy Policy</a>. This does not include promotional messages.</span></label><div class="cookie-actions"><button type="button" data-cancel>Cancel</button><button type="button" data-continue disabled>Continue to WhatsApp</button></div>';document.body.append(consent);let destination='';const check=consent.querySelector('input'),go=consent.querySelector('[data-continue]');check.addEventListener('change',()=>go.disabled=!check.checked);const cancel=()=>consent.close();consent.querySelector('[data-cancel]').addEventListener('click',cancel);consent.querySelector('.dialog-close').addEventListener('click',cancel);go.addEventListener('click',()=>{if(!check.checked||!destination)return;const url=new URL(destination);if(url.origin!=='https://wa.me')return;consent.close();window.open(url.href,'_blank','noopener,noreferrer')});
document.addEventListener('click',event=>{const link=event.target.closest('a[href]');if(!link)return;let url;try{url=new URL(link.href)}catch{return}if(url.origin!=='https://wa.me')return;if(link.id==='whatsapp-enquiry'&&document.querySelector('#contact-consent')?.checked)return;event.preventDefault();destination=link.href;check.checked=false;go.disabled=true;consent.showModal()});
})();
